import { PulsingDot } from '../PulsingDot'
import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { X } from 'lucide-react-native'
import { AnimatePresence, MotiText } from 'moti'

export const CodeChangePlaceholderBlock = ({
	placeholderText,
	isCancelled
}: {
	placeholderText: string
	isCancelled: boolean
}) => {
	const { theme } = useTheme()
	return (
		<>
			{isCancelled ? (
				<X size={18} color={colors[theme].gray[400]} />
			) : (
				<PulsingDot />
			)}
			<AnimatePresence exitBeforeEnter>
				<MotiText
					key={placeholderText}
					from={{ opacity: 0, translateY: -6 }}
					animate={{ opacity: 1, translateY: 0 }}
					exit={{ opacity: 0, translateY: 6 }}
					transition={{ type: 'timing', duration: 300 }}
					style={styles.placeholderText(theme)}
				>
					{placeholderText}
				</MotiText>
			</AnimatePresence>
		</>
	)
}

const styles = defineStyles({
	placeholderText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[600]
	})
})
